/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be a valid date in YYYY-MM-DD format.',
  DISCOUNT_INVALID: 'Discount must be a number between 0 and 100.',
  INVOICE_INVALID: 'An invoice must be an object with a lines array.',
  LINE_INVALID: 'A line must have a positive quantity and a non-negative unit price.',
  LINE_NOT_FOUND: 'No line with that SKU on the invoice.',
  NO_LINES: 'An invoice must have at least one line.',
  NOT_DRAFT: 'Cannot modify an invoice that is not in draft status.',
  QTY_INVALID: 'Quantity must be a positive integer.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

